@OptIn(ExperimentalMaterial3Api::class)
@Composable fun HarnessScreen(onBack:()->Unit){
 val context=LocalContext.current
 val model:HarnessViewModel=viewModel(factory=HarnessViewModel.factory(HttpHarnessApi(),KeystoreHarnessTokenStore(context)))
 val state by model.state.collectAsStateWithLifecycle()
 val lifecycle=LocalLifecycleOwner.current.lifecycle
 DisposableEffect(lifecycle,model){val observer=LifecycleEventObserver{_,event->when(event){Lifecycle.Event.ON_START->model.setScreenActive(true);Lifecycle.Event.ON_STOP->model.setScreenActive(false);else->Unit}};lifecycle.addObserver(observer);model.setScreenActive(lifecycle.currentState.isAtLeast(Lifecycle.State.STARTED));onDispose{lifecycle.removeObserver(observer);model.setScreenActive(false)}}
 Scaffold(containerColor=FffBackground,topBar={TopAppBar(title={Text(state.selected?.title?:"AI Harness",fontWeight=FontWeight.Bold,maxLines=1,overflow=TextOverflow.Ellipsis)},navigationIcon={IconButton(if(state.selected!=null)model::close else onBack){Icon(Icons.AutoMirrored.Rounded.ArrowBack,"Назад")}},colors=TopAppBarDefaults.topAppBarColors(containerColor=FffBackground))}){padding->Box(Modifier.fillMaxSize().padding(padding)){when(val phase=state.phase){HarnessPhase.Unpaired->PairIntro(state.error,state.loading,model::pair);is HarnessPhase.Pairing->PairCode(phase.code,state.error);HarnessPhase.Revoking->Revoking(state,model::retryPendingRevoke);HarnessPhase.Paired->if(state.selected==null)ConversationList(state,model) else ConversationChat(state,model)}}}
}

@Composable private fun ConversationList(state:HarnessState,model:HarnessViewModel){var modal by remember{mutableStateOf<String?>(null)};var title by remember{mutableStateOf("")};Column(Modifier.fillMaxSize()){Row(Modifier.fillMaxWidth().padding(horizontal=16.dp,vertical=6.dp),verticalAlignment=Alignment.CenterVertically){Text(if(state.showArchived)"Архив" else "Диалоги",fontSize=22.sp,fontWeight=FontWeight.Bold,modifier=Modifier.weight(1f));TextButton(model::toggleArchived){Text(if(state.showArchived)"Активные" else "Архив")};IconButton({title="";modal="new"}){Icon(Icons.Rounded.Add,"Новый диалог",tint=FffMint)}};if(state.loading&&state.conversations.isEmpty())Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){CircularProgressIndicator(color=FffMint)}else if(state.conversations.isEmpty())Text("Здесь появятся ваши диалоги",color=FffMuted,modifier=Modifier.padding(24.dp))else LazyColumn(contentPadding=PaddingValues(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){items(state.conversations,key={it.id}){c->Surface(onClick={model.open(c)},shape=RoundedCornerShape(18.dp),color=if(c.kind==ConversationKind.EE)FffViolet.copy(alpha=.15f) else FffSurface,border=BorderStroke(1.dp,if(c.kind==ConversationKind.EE)FffViolet.copy(alpha=.5f) else FffLine)){Row(Modifier.fillMaxWidth().padding(14.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(42.dp).background(if(c.kind==ConversationKind.EE)FffViolet else FffMint.copy(alpha=.16f),RoundedCornerShape(13.dp)),contentAlignment=Alignment.Center){Icon(if(c.kind==ConversationKind.EE)Icons.Rounded.PushPin else Icons.Rounded.Chat,null,tint=if(c.kind==ConversationKind.EE)Color.White else FffMint)};Column(Modifier.weight(1f).padding(horizontal=12.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text(c.title,fontWeight=FontWeight.Bold,modifier=Modifier.weight(1f));if(c.kind==ConversationKind.EE)Text("TELEGRAM",fontFamily=FontFamily.Monospace,fontSize=9.sp,color=FffMint)};Text(c.lastMessage?:"Пока нет сообщений",color=FffMuted,maxLines=2,overflow=TextOverflow.Ellipsis,fontSize=13.sp);Text(formatHarnessActivity(c.updatedAt),color=FffMuted,fontSize=10.sp,modifier=Modifier.padding(top=4.dp))}}}}};state.error?.let{Text(it,color=Color(0xFFFF7C9B),modifier=Modifier.padding(16.dp))}
 if(modal=="new")FffModal("Новый диалог",{modal=null},"Создать",{model.create(title);modal=null},confirmEnabled=title.trim().isNotEmpty()){FffTextInput("Название",title,{title=it.take(120)})}}
}

@Composable private fun ConversationChat(state:HarnessState,model:HarnessViewModel){val c=state.selected!!;var menu by remember{mutableStateOf(false)};var modal by remember{mutableStateOf<String?>(null)};var title by remember(c.id){mutableStateOf(c.title)};val list=rememberLazyListState();var followTail by remember(c.id){mutableStateOf(true)};var wasScrolling by remember(c.id){mutableStateOf(false)};LaunchedEffect(list,c.id){snapshotFlow{list.isScrollInProgress}.collect{scrolling->val info=list.layoutInfo;followTail=nextHarnessFollowTail(followTail,wasScrolling,scrolling,info.visibleItemsInfo.lastOrNull()?.index,info.totalItemsCount);wasScrolling=scrolling}};LaunchedEffect(state.sending){if(state.sending)followTail=true};LaunchedEffect(state.messages.lastOrNull()?.id){if(shouldAutoScrollHarnessTail(followTail,list.isScrollInProgress)&&state.messages.isNotEmpty())list.animateScrollToItem(state.messages.lastIndex)};Column(Modifier.fillMaxSize()){Row(Modifier.fillMaxWidth().padding(horizontal=10.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(if(c.kind==ConversationKind.EE)"Синхронизация с топиком EE" else "Отдельный контекст",fontSize=11.sp,color=if(c.kind==ConversationKind.EE)FffMint else FffMuted)};if(c.kind!=ConversationKind.EE){IconButton({menu=true}){Icon(Icons.Rounded.MoreVert,"Действия")};DropdownMenu(menu,{menu=false}){DropdownMenuItem({Text("Переименовать")},{menu=false;title=c.title;modal="rename"},leadingIcon={Icon(Icons.Rounded.Edit,null)});DropdownMenuItem({Text(if(c.archived)"Восстановить" else "В архив")},{menu=false;modal="archive"},leadingIcon={Icon(Icons.Rounded.Archive,null)});DropdownMenuItem({Text("Удалить",color=Color(0xFFFF7C9B))},{menu=false;modal="delete"},leadingIcon={Icon(Icons.Rounded.Delete,null,tint=Color(0xFFFF7C9B))})}}};if(state.nextBefore!=null)TextButton(model::loadOlder,Modifier.align(Alignment.CenterHorizontally),enabled=!state.loadingOlder){Text(if(state.loadingOlder)"Загрузка…" else "Показать предыдущие")};LazyColumn(Modifier.weight(1f).fillMaxWidth(),state=list,contentPadding=PaddingValues(12.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){items(state.messages,key={it.id}){m->val mine=m.role=="user";Row(Modifier.fillMaxWidth(),horizontalArrangement=if(mine)Arrangement.End else Arrangement.Start){Column(Modifier.widthIn(max=310.dp).background(if(mine)FffViolet.copy(alpha=.24f) else FffSurface,RoundedCornerShape(16.dp)).padding(12.dp)){Text(messageLabel(m),fontSize=9.sp,fontFamily=FontFamily.Monospace,color=FffMint);Text(m.content)}}};if(state.sending)item("pending"){Row(verticalAlignment=Alignment.CenterVertically){CircularProgressIndicator(Modifier.size(17.dp),strokeWidth=2.dp,color=FffMint);Text(if(c.kind==ConversationKind.EE)"Ожидаю ответ из Telegram…" else "Агент думает…",color=FffMuted,modifier=Modifier.padding(start=8.dp))}}};state.error?.let{Row(Modifier.fillMaxWidth().padding(horizontal=12.dp),verticalAlignment=Alignment.CenterVertically){Text(it,color=Color(0xFFFF7C9B),modifier=Modifier.weight(1f));if(state.retryText!=null)TextButton(model::retry){Text("Повторить")}}};Row(Modifier.fillMaxWidth().imePadding().padding(8.dp),verticalAlignment=Alignment.Bottom){OutlinedTextField(state.draft,model::updateDraft,Modifier.weight(1f),placeholder={Text("Сообщение")},maxLines=6,isError=state.composerError!=null,supportingText=if(state.composerError!=null){{Text(state.composerError!!)}}else null,shape=RoundedCornerShape(18.dp));IconButton(model::send,enabled=state.draft.isNotBlank()&&!state.sending){Icon(Icons.Rounded.Send,"Отправить",tint=FffMint)}}}
 if(modal=="rename")FffModal("Название диалога",{modal=null},"Сохранить",{model.rename(title);modal=null},confirmEnabled=title.trim().isNotEmpty()){FffTextInput("Название",title,{title=it.take(120)})}
 if(modal=="archive")FffModal(if(c.archived)"Восстановить диалог?" else "Переместить в архив?",{modal=null},if(c.archived)"Восстановить" else "В архив",{model.archive(!c.archived);modal=null}){Text("История сообщений сохранится.",color=FffMuted)}
 if(modal=="delete")FffModal("Удалить диалог навсегда?",{modal=null},"Удалить",{model.delete();modal=null},destructive=true){Text("Диалог и вся его история будут удалены без возможности восстановления.",color=FffMuted)}
}
internal fun messageLabel(m:ServerMessage):String{val role=when(m.role.replace('-','_')){"user"->"USER";"assistant"->"AI";"tool"->"TOOL";else->m.role.uppercase()};val source=when(m.source.replace('-','_')){"telegram_user","telegram_bot"->"TELEGRAM";"harness"->"HARNESS";"agent"->"AGENT";else->m.source.uppercase()};return listOfNotNull(role,source,m.authorName?.takeIf{it.isNotBlank()}).joinToString(" · ")}
internal fun shouldFollowHarnessTail(lastVisibleIndex:Int?,totalItems:Int,threshold:Int=2):Boolean=totalItems==0||lastVisibleIndex!=null&&lastVisibleIndex>=totalItems-1-threshold
internal fun nextHarnessFollowTail(current:Boolean,wasScrolling:Boolean,isScrolling:Boolean,lastVisibleIndex:Int?,totalItems:Int):Boolean=when{isScrolling->false;wasScrolling->shouldFollowHarnessTail(lastVisibleIndex,totalItems);else->current}
internal fun shouldAutoScrollHarnessTail(followTail:Boolean,isScrollInProgress:Boolean):Boolean=followTail&&!isScrollInProgress
internal fun formatHarnessActivity(value:String):String=runCatching{OffsetDateTime.parse(value).format(DateTimeFormatter.ofPattern("dd.MM.yyyy · HH:mm"))}.getOrElse{value.take(16).ifBlank{"—"}}

@Composable private fun PairIntro(error:String?,busy:Boolean,pair:()->Unit)=Column(Modifier.fillMaxSize().padding(20.dp),verticalArrangement=Arrangement.Center,horizontalAlignment=Alignment.CenterHorizontally){Icon(Icons.Rounded.Link,null,tint=FffMint,modifier=Modifier.size(48.dp));Text("Подключить ассистента",fontWeight=FontWeight.Bold);Text("Подтверждение выполняется лично вами в Telegram.",color=FffMuted,modifier=Modifier.padding(vertical=12.dp));Button(pair,enabled=!busy){Text(if(busy)"Подключаю…" else "Получить код")};error?.let{Text(it,color=Color(0xFFFF7C9B),modifier=Modifier.padding(top=12.dp))}}
@Composable private fun PairCode(code:String,error:String?)=Column(Modifier.fillMaxSize().padding(20.dp),verticalArrangement=Arrangement.Center,horizontalAlignment=Alignment.CenterHorizontally){Text("КОД ПОДКЛЮЧЕНИЯ",color=FffMint,fontFamily=FontFamily.Monospace);Text(code,fontSize=36.sp,fontWeight=FontWeight.Bold,modifier=Modifier.padding(14.dp));Text("Отправьте боту в топике ИИ:");Text("/pair $code",fontFamily=FontFamily.Monospace,color=FffViolet,modifier=Modifier.padding(10.dp));Text("Ожидаю подтверждение…",color=FffMuted);error?.let{Text(it,color=Color(0xFFFF7C9B))}}
@Composable private fun Revoking(state:HarnessState,retry:()->Unit)=Column(Modifier.fillMaxSize().padding(20.dp),verticalArrangement=Arrangement.Center,horizontalAlignment=Alignment.CenterHorizontally){if(state.loading)CircularProgressIndicator(color=FffMint);Text("Завершаю отключение…",fontWeight=FontWeight.Bold,modifier=Modifier.padding(12.dp));state.error?.let{Text(it,color=Color(0xFFFF7C9B));Button(retry){Text("Повторить")}}}
